import {jobs,items,monsters,quests,elements} from './data.js';
export const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
export function derived(h){const s=h.stats,w=items[h.gear.weapon]||{},a=items[h.gear.armor]||{},cards=Object.values(h.cards||{});const bonus=cards.length*2;return{hp:90+h.base*16+s.VIT*12,sp:25+s.INT*5+h.base*2,atk:8+h.base*2+s.STR*2+(w.atk||0)+bonus,matk:8+h.base+s.INT*3+(w.matk||0)+bonus,def:s.VIT*1.2+(a.def||0),mdef:s.INT+s.VIT*.3,hit:80+h.base+s.DEX*2,flee:h.base+s.AGI*1.4,aspd:clamp(150+s.AGI*.5+s.DEX*.15,150,190),crit:clamp(.01+s.LUK*.003,0,.4),dodge:clamp(s.LUK*.001,0,.1),capacity:200+s.STR*20};}
export function hitChance(hit,flee){return clamp((80+hit-flee)/100,.05,.95)}
export function attackInterval(aspd){return (200-aspd)*.04}
export function damage(atk,def,mult=1,element=1,crit=false){return Math.max(1,Math.floor(atk*100/(100+Math.max(0,def))*mult*element*(crit?1.5:1)))}
export function initial(){return{version:1,zeny:100,zone:0,leader:0,tactic:'balanced',auto:false,quest:0,questKills:0,finished:false,kills:0,bounty:0,bountyClaimed:false,bountyDay:new Date().toISOString().slice(0,10),inventory:{potion:12,ether:4},heroes:['Остап','Зоряна','Левко','Соломія','Данило','Рута'].map((name,i)=>{let h={id:i,name,job:'novice',base:1,jobLevel:1,xp:0,jxp:0,statPoints:5,skillPoints:0,skillLevel:1,stats:{STR:4,AGI:4,VIT:4,INT:4,DEX:4,LUK:4},gear:{weapon:null,armor:null},cards:{},hp:154,sp:49,x:12+(i%3),y:13+Math.floor(i/3),cooldown:0,skillCooldown:0};return h}),lastSeen:Date.now(),afkZone:null,discovered:[],log:[]};}
export function addItem(s,id,n=1){let weight=Object.entries(s.inventory).reduce((v,[k,q])=>v+(items[k]?.weight||1)*q,0);if(weight+n*(items[id]?.weight||1)>s.heroes.reduce((v,h)=>v+derived(h).capacity,0))return false;s.inventory[id]=(s.inventory[id]||0)+n;return true;}
export function gainXP(h,n){h.xp+=n;h.jxp+=n;while(h.base<99&&h.xp>=h.base*50){h.xp-=h.base*50;h.base++;h.statPoints+=3;h.hp=derived(h).hp;h.sp=derived(h).sp;}while(h.jobLevel<50&&h.jxp>=h.jobLevel*35){h.jxp-=h.jobLevel*35;h.jobLevel++;h.skillPoints++;}}
export function advance(h,id){if(!(jobs[h.job].branches||[]).includes(id))return false;let required=h.job==='novice'?10:40;if(h.jobLevel<required)return false;h.job=id;h.jobLevel=1;h.jxp=0;h.skillPoints=0;h.skillLevel=1;return true;}
export function reward(s,m,rng=Math.random){s.zeny+=m.zeny;s.kills++;s.bounty++;s.heroes.forEach(h=>gainXP(h,m.exp));addItem(s,m.drop);if(!s.discovered.includes(m.id))s.discovered.push(m.id);let drops=[m.drop];if(rng()<.12){addItem(s,'potion');drops.push('potion');}if(rng()<clamp(.02+s.heroes[s.leader].stats.LUK*.0005,0,.05)){addItem(s,'card:'+m.id);drops.push('card:'+m.id);}if(!s.finished&&m.zone===quests[s.quest].zone)s.questKills++;return drops;}
export function claimQuest(s){let q=quests[s.quest];if(s.finished||s.questKills<q.goal)return false;s.zeny+=q.reward;s.heroes.forEach(h=>gainXP(h,q.reward));if(s.quest===quests.length-1)s.finished=true;else{s.quest++;s.questKills=0;}return true;}
export function useItem(s,id){if(!(s.inventory[id]>0))return false;let h=s.heroes[s.leader],d=derived(h);if(id==='potion'){h.hp=Math.min(d.hp,h.hp+d.hp*.6)}else if(id==='ether'){h.sp=d.sp}else return false;s.inventory[id]--;return true;}
export function equip(s,id){let item=items[id],h=s.heroes[s.leader];if(!s.inventory[id]||!['weapon','armor'].includes(item?.type))return false;let slot=item.type;if(h.cards[slot])return false;if(h.gear[slot])addItem(s,h.gear[slot]);h.gear[slot]=id;s.inventory[id]--;return true;}
export function socket(s,id,slot='weapon'){let h=s.heroes[s.leader];if(!id.startsWith('card:')||!s.inventory[id]||!items[h.gear[slot]]?.sockets||h.cards[slot])return false;h.cards[slot]=id;s.inventory[id]--;return true;}
export function settleOffline(s,now=Date.now()){const elapsed=clamp((now-s.lastSeen)/1000,0,4*3600);s.lastSeen=now;if(s.afkZone===null||elapsed<60)return null;const eligible=monsters.filter(m=>m.zone===s.afkZone&&!m.boss&&m.level<=Math.min(...s.heroes.map(h=>h.base))+2);if(!eligible.length)return null;let count=Math.min(240,Math.floor(elapsed/60)),z=0,xp=0;for(let i=0;i<count;i++){let m=eligible[i%eligible.length];z+=m.zeny;xp+=Math.floor(m.exp*.35);addItem(s,m.drop);}s.zeny+=z;s.heroes.forEach(h=>gainXP(h,xp));return{count,zeny:z,xp};}
// Breadth-first search on equal-cost tiles is shortest-path pathfinding.
export function pathfind(start,end,blocked,size=26){const key=(x,y)=>x+','+y;let q=[[Math.round(start.x),Math.round(start.y)]],prev=new Map([[key(...q[0]),null]]);while(q.length){const [x,y]=q.shift();if(x===end.x&&y===end.y){let p=[],k=key(x,y);while(prev.get(k)!==null){p.push(k.split(',').map(Number));k=prev.get(k);}return p.reverse();}for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){let a=x+dx,b=y+dy,k=key(a,b);if(a<0||b<0||a>=size||b>=size||blocked(a,b)||prev.has(k))continue;prev.set(k,key(x,y));q.push([a,b]);}}return[];}
export function elementMultiplier(a,d){return elements[a]?.[d]||1;}
